// Canonical DB types: supabase/migrations -> local Supabase DB -> database.types.generated.ts
//   npm run db:types        regenerate the file
//   npm run db:types:check  fail if the committed file is stale vs the local DB
// Requires `supabase start` with all migrations applied (`supabase migration up --local`).
import { execFileSync } from "node:child_process"
import { readFileSync, writeFileSync } from "node:fs"

const target = new URL("../database.types.generated.ts", import.meta.url)
const header =
  "// GENERATED by `npm run db:types` from supabase/migrations (local DB). Do not edit by hand.\n"

const out = execFileSync(
  process.platform === "win32" ? "npx.cmd" : "npx",
  ["--no-install", "supabase", "gen", "types", "typescript", "--local"],
  { encoding: "utf8", shell: process.platform === "win32", stdio: ["ignore", "pipe", "ignore"] },
)
const next = header + out.replace(/\r\n/g, "\n")

if (process.argv.includes("--check")) {
  const current = readFileSync(target, "utf8").replace(/\r\n/g, "\n")
  if (current !== next) {
    console.error("database.types.generated.ts is stale. Run `npm run db:types` and commit the result.")
    process.exit(1)
  }
  console.log("database.types.generated.ts is up to date.")
} else {
  writeFileSync(target, next)
  console.log("Wrote database.types.generated.ts")
}
